// Characters: loads sprite-forge sheets from /public/sprites/<name>/ and falls back to built-in art.
// Coding agents: do not edit this file. Point config.js at sprite names instead.

import { builtinCharacter, makeCanvas } from './art.js'

// Opaque bounding box of a frame, used to put feet on the ground and center sprites on hitboxes.
function bbox(img) {
  const g = img.getContext('2d')
  const { data } = g.getImageData(0, 0, img.width, img.height)
  let x0 = img.width
  let y0 = img.height
  let x1 = -1
  let y1 = -1
  for (let y = 0; y < img.height; y++) {
    for (let x = 0; x < img.width; x++) {
      if (data[(y * img.width + x) * 4 + 3] > 0) {
        if (x < x0) x0 = x
        if (y < y0) y0 = y
        if (x > x1) x1 = x
        if (y > y1) y1 = y
      }
    }
  }
  if (x1 < 0) return { x: 0, y: 0, w: img.width, h: img.height }
  return { x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1 }
}

function frame(img) {
  return { img, box: bbox(img), glow: null }
}

class Character {
  // anims: { walk_right: [frame], walk_left, idle_right, idle_left, jump_right, jump_left, knocked_out, cheer }
  constructor(name, anims, source) {
    this.name = name
    this.anims = anims
    this.source = source
    const ref = (anims.idle_right || anims.walk_right)[0].box
    this.hitW = Math.max(8, Math.min(16, ref.w - 2))
    this.hitH = Math.max(8, Math.min(28, ref.h - 1))
  }

  frames(anim, dir) {
    const side = dir < 0 ? 'left' : 'right'
    return this.anims[`${anim}_${side}`] || this.anims[anim] || this.anims[`idle_${side}`] || this.anims.walk_right
  }

  // Draw so the sprite's feet sit on the hitbox bottom and it's centered horizontally.
  draw(g, anim, dir, t, x, y, w, h, opts = {}) {
    const list = this.frames(anim, dir)
    const f = list[Math.floor(t) % list.length]
    const dx = Math.round(x + w / 2 - (f.box.x + f.box.w / 2))
    const dy = Math.round(y + h - (f.box.y + f.box.h))
    if (opts.flipY) {
      g.save()
      g.translate(dx, dy + f.img.height)
      g.scale(1, -1)
      g.drawImage(f.img, 0, 0)
      g.restore()
      return
    }
    if (opts.glow) {
      if (!f.glow) f.glow = tinted(f.img, opts.glow)
      for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) g.drawImage(f.glow, dx + ox, dy + oy)
    }
    if (opts.squash) {
      const sh = Math.max(3, Math.round(f.box.h / 3))
      g.drawImage(f.img, f.box.x, f.box.y, f.box.w, f.box.h, dx + f.box.x, Math.round(y + h) - sh, f.box.w, sh)
      return
    }
    g.drawImage(f.img, dx, dy)
  }
}

function tinted(img, color) {
  const c = makeCanvas(img.width, img.height)
  const g = c.getContext('2d')
  g.drawImage(img, 0, 0)
  g.globalCompositeOperation = 'source-in'
  g.fillStyle = color
  g.fillRect(0, 0, c.width, c.height)
  return c
}

function fromBuiltin(name, kind) {
  const b = builtinCharacter(kind)
  const side = (list, s) => list.map((f) => frame(f[s]))
  const anims = {
    walk_right: side(b.walk, 'right'),
    walk_left: side(b.walk, 'left'),
    idle_right: side(b.idle, 'right'),
    idle_left: side(b.idle, 'left'),
    jump_right: side(b.jump, 'right'),
    jump_left: side(b.jump, 'left'),
  }
  anims.knocked_out = anims.jump_right
  anims.cheer = anims.idle_right
  return new Character(name, anims, 'builtin')
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image()
    img.onload = () => resolve(img)
    img.onerror = () => reject(new Error(`missing ${src}`))
    img.src = src
  })
}

async function fromSheet(name) {
  const base = `/sprites/${name}/`
  const res = await fetch(`${base}${name}.json`)
  if (!res.ok) throw new Error(`no sprite data for ${name}`)
  const meta = await res.json()
  const sheet = await loadImage(base + meta.image)
  const fw = meta.frameWidth
  const fh = meta.frameHeight
  const cols = meta.columns || Math.floor(sheet.width / fw)
  const cut = (i) => {
    const c = makeCanvas(fw, fh)
    c.getContext('2d').drawImage(sheet, (i % cols) * fw, Math.floor(i / cols) * fh, fw, fh, 0, 0, fw, fh)
    return frame(c)
  }
  const anims = {}
  for (const [key, a] of Object.entries(meta.animations || {})) anims[key] = a.frames.map(cut)
  if (!anims.walk_right || !anims.walk_left) throw new Error(`${name}: sheet has no walk_left / walk_right`)
  anims.idle_right ||= [anims.walk_right[1] || anims.walk_right[0]]
  anims.idle_left ||= [anims.walk_left[1] || anims.walk_left[0]]
  anims.jump_right ||= anims.walk_right
  anims.jump_left ||= anims.walk_left
  return new Character(name, anims, 'sheet')
}

// specs: { key: { sprite: 'folder name', fallback: 'player' | 'aphid' | 'mite' | 'moth' } }
export async function loadCharacters(specs) {
  const out = {}
  const notes = []
  await Promise.all(
    Object.entries(specs).map(async ([key, spec]) => {
      try {
        if (!spec.sprite) throw new Error('no sprite set')
        out[key] = await fromSheet(spec.sprite)
      } catch (e) {
        out[key] = fromBuiltin(key, spec.fallback || 'player')
        notes.push(`${key}: using built-in art (${e.message})`)
      }
    }),
  )
  if (notes.length) console.info('[characters]', notes.join('; '))
  return out
}
